(window.CLAVE_TEST=window.CLAVE_TEST||{})[14]=[{"a":"Artículo 1 — Carácter del Defensor del Pueblo R1","q":[{"i":"14-199","p":"Ley Orgánica 3/1981, de 6 de abril, del Defensor del Pueblo. El Defensor del Pueblo es el alto comisionado de las Cortes Generales designado por estas para la defensa de los derechos comprendidos en el Título I de la Constitución, a cuyo efecto podrá supervisar la actividad de la Administración, dando cuenta a:","o":["El Gobierno.","Las Cortes Generales.","Conjuntamente, el Gobierno y a las Cortes Generales.","El Congreso."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Las Cortes Generales.</mark></span><span class=\"ref-norma\">Art. 1.1 · Ley Orgánica 3/1981, de 6 de abril, del Defensor del Pueblo</span>. El Defensor del Pueblo es el alto comisionado de las Cortes Generales y debe dar cuenta de su gestión a estas (Art. 1.1 LO 3/1981)."},{"i":"14-205","p":"(LO 3/1981) ¿De quién será el Defensor del Pueblo alto comisionado?","o":["Del Gobierno.","De las Administraciones Públicas.","Del Ministerio Fiscal.","De las Cortes Generales."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">De las Cortes Generales.</mark></span><span class=\"ref-norma\">Art. 1.1 · El Defensor del Pueblo</span>. El Art. 1.1 de la LO 3/1981 lo define como el alto comisionado de las Cortes Generales."},{"i":"14-216","p":"(LO 3/1981) Ley Orgánica 3/1981, de 6 de abril, del Defensor del Pueblo. Señale la INCORRECTA.","o":["El Defensor del Pueblo es el alto comisionado de las Cortes Generales designado por estas para la defensa de los derechos comprendidos en el título I de la Constitución.","Podrá supervisar la actividad de la Administración, dando cuenta al Gobierno.","Ejercerá las funciones que le encomienda la Constitución.","Ejercerá las funciones que le encomienda la presente Ley."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Podrá supervisar la actividad de la Administración, dando cuenta al Gobierno.</mark></span><span class=\"ref-norma\">Art. 1.1 · Ley Orgánica 3/1981, de 6 de abril, del Defensor del Pueblo</span>. El Art. 1.1 de la LO 3/1981 establece que el DP supervisa la Administración, dando cuenta a las Cortes Generales, no al Gobierno."},{"i":"14-221","p":"Ley Orgánica 3/1981, de 6 de abril, del Defensor del Pueblo. El Defensor del Pueblo es:","o":["El alto comisionado de las Cortes Generales designado por estas para la defensa de los derechos comprendidos en el Título II de la Constitución.","El alto comisionado de las Cortes Generales designado por estas para la defensa de los derechos y libertades comprendidos en el Título I de la Constitución.","El alto comisionado de las Cortes Generales designado por estas para la defensa de los derechos comprendidos en el Título III de la Constitución.","El alto comisionado de España designado por las Cortes Generales para la defensa de los derechos comprendidos en el Título I de la Constitución."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">El alto comisionado de las Cortes Generales designado por estas para la defensa de los derechos y libertades comprendidos en el Título I …</mark></span><span class=\"ref-norma\">Art. 1 · Ley Orgánica 3/1981, de 6 de abril, del Defensor del Pueblo</span>. El Art. 1 de la LO 3/1981 define al Defensor del Pueblo como alto comisionado de las Cortes Generales para la defensa de los derechos comprendidos en el Título I de la Constitución."},{"i":"14-ia-28","p":"Reglamento del Defensor del Pueblo, art. 1.2. El Protocolo facultativo de la Convención contra la tortura cuyas funciones de Mecanismo Nacional de Prevención ejerce el Defensor del Pueblo fue hecho en Nueva York el:","o":["10 de diciembre de 1948.","4 de noviembre de 1950.","18 de diciembre de 2002.","18 de diciembre de 1979."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">18 de diciembre de 2002</mark></span>El <span class=\"ref-norma\">art. 1.2 del Reglamento de Organización y Funcionamiento del Defensor del Pueblo</span> dispone: <span class=\"ref-concepto\">\"previstas en el Protocolo facultativo de la Convención contra la tortura y otros tratos o penas crueles, inhumanos o degradantes, hecho en Nueva York el 18 de diciembre de 2002, y dará cuenta de su actividad a las Cortes Generales y al Subcomité para la Prevención de la Tortura de la Organización de las Naciones Unidas\"</span>. Por qué fallan las otras: las otras fechas corresponden a otros textos (Declaración Universal de 1948, Convenio de Roma de 1950, CEDAW de 1979); el Protocolo es de 2002. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA · Dificultad: Media)</em>"},{"i":"14-ia-101","p":"Ley Orgánica 3/1981, de 6 de abril, del Defensor del Pueblo. Naturaleza. El Defensor del Pueblo es el alto comisionado de las Cortes Generales designado por éstas para la defensa de los derechos comprendidos en el Título I de la Constitución, a cuyo efecto podrá supervisar la actividad de la Administración, dando cuenta:","o":["al Gobierno y a las Cortes Generales.","al Congreso de los Diputados y al Senado por separado.","a las Cortes Generales.","a la Comisión Mixta Congreso-Senado de relaciones con el Defensor del Pueblo."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">a las Cortes Generales</mark></span>El <span class=\"ref-norma\">art. 1 de la LO 3/1981</span> dispone: <span class=\"ref-concepto\">\"a cuyo efecto podrá supervisar la actividad de la Administración, dando cuenta a las Cortes Generales.\"</span> Rinde cuentas ante las Cortes Generales, no ante el Gobierno."},{"i":"14-ia-176","p":"Reglamento de Organización y Funcionamiento del Defensor del Pueblo, aprobado por las Mesas del Congreso y del Senado, a propuesta del Defensor del Pueblo, en su reunión conjunta de 6 de abril de 1983. Mecanismo Nacional de Prevención de la Tortura. El Defensor del Pueblo ejercerá las funciones de Mecanismo Nacional de Prevención de la Tortura, previstas en el Protocolo facultativo de la Convención contra la tortura, y dará cuenta de su actividad a las Cortes Generales y:","o":["al Consejo de Derechos Humanos de las Naciones Unidas.","al Subcomité para la Prevención de la Tortura de la Organización de las Naciones Unidas.","al Comité contra la Tortura del Consejo de Europa.","al Alto Comisionado de las Naciones Unidas para los Derechos Humanos, sin perjuicio de lo que establezcan los tratados internacionales."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">al Subcomité para la Prevención de la Tortura de la Organización de las Naciones Unidas</mark></span>El <span class=\"ref-norma\">art. 1.2 de la Reglamento del Defensor del Pueblo</span> dispone: <span class=\"ref-concepto\">\"y dará cuenta de su actividad a las Cortes Generales y al Subcomité para la Prevención de la Tortura de la Organización de las Naciones Unidas.\"</span> Subcomité para la Prevención de la Tortura de la ONU."}]},{"a":"Artículo 4 — Nombramiento y toma de posesión ✱","q":[{"i":"14-ia-1","p":"LO 3/1981, del Defensor del Pueblo, art. 4.1. ¿Quiénes acreditan conjuntamente con sus firmas el nombramiento del Defensor del Pueblo, que se publicará en el «Boletín Oficial del Estado»?","o":["El Presidente del Gobierno y el Presidente del Congreso.","Las Mesas de ambas Cámaras reunidas conjuntamente.","Los Presidentes del Congreso y del Senado.","El Presidente de la Comisión Mixta Congreso-Senado."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Los Presidentes del Congreso y del Senado</mark></span>El <span class=\"ref-norma\">art. 4.1 de la LO 3/1981, del Defensor del Pueblo</span> dispone: <span class=\"ref-concepto\">\"Los Presidentes del Congreso y del Senado acreditarán conjuntamente con sus firmas el nombramiento del Defensor del Pueblo que se publicará en el «Boletín Oficial del Estado»\"</span>. Por qué fallan las otras: las Mesas de ambas Cámaras reunidas conjuntamente intervienen en la toma de posesión (art. 4.2), no en la acreditación del nombramiento; el Presidente del Gobierno y el de la Comisión Mixta no firman el nombramiento. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA · Dificultad: Fácil)</em>"},{"i":"14-ia-110","p":"Ley Orgánica 3/1981, de 6 de abril, del Defensor del Pueblo. Nombramiento. El nombramiento del Defensor del Pueblo lo acreditarán conjuntamente con sus firmas los Presidentes del Congreso y del Senado, y se publicará en:","o":["el «Boletín Oficial del Estado».","el «Boletín Oficial de las Cortes Generales».","los Boletines Oficiales del Congreso y del Senado.","el «Diario de Sesiones» de ambas Cámaras."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">el «Boletín Oficial del Estado»</mark></span>El <span class=\"ref-norma\">art. 4.1 de la LO 3/1981</span> dispone: <span class=\"ref-concepto\">\"acreditarán conjuntamente con sus firmas el nombramiento del Defensor del Pueblo que se publicará en el «Boletín Oficial del Estado».\"</span> Publicación en el BOE."},{"i":"14-ia-111","p":"Ley Orgánica 3/1981, de 6 de abril, del Defensor del Pueblo. Toma de posesión. El Defensor del Pueblo tomará posesión de su cargo ante:","o":["el Presidente del Congreso de los Diputados, prestando juramento o promesa de acatamiento a la Constitución, sin perjuicio de lo que establezcan los tratados internacionales.","el Pleno del Congreso, prestando juramento o promesa de fiel desempeño de su función.","las Mesas de ambas Cámaras reunidas conjuntamente, prestando juramento o promesa de fiel desempeño de su función.","la Comisión Mixta Congreso-Senado, prestando juramento o promesa de lealtad a las Cortes."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">las Mesas de ambas Cámaras reunidas conjuntamente, prestando juramento o promesa de fiel desempeño de su función</mark></span>El <span class=\"ref-norma\">art. 4.2 de la LO 3/1981</span> dispone: <span class=\"ref-concepto\">\"tomará posesión de su cargo ante las Mesas de ambas Cámaras reunidas conjuntamente, prestando juramento o promesa de fiel desempeño de su función.\"</span> Ante las Mesas de ambas Cámaras reunidas conjuntamente."}]},{"a":"Artículo 10 — Quién puede dirigirse al Defensor","q":[{"i":"14-19","p":"Ley Orgánica 3/1981, de 6 de abril, del Defensor del Pueblo. Iniciación y contenido de la investigación. ¿Quién podrá solicitar, mediante escrito motivado, la intervención del Defensor del Pueblo para el esclarecimiento de actos y conductas concretas producidas en las Administraciones públicas, que afectan a un grupo de ciudadanos, en el ámbito de su competencia? Indique la incorrecta.","o":["Los Diputados y Senadores individualmente.","Las Comisiones de investigación o relacionadas con la defensa general o parcial de los derechos y libertades públicas.","Principalmente la Comisión Mixta Congreso-Senado de relaciones con el Defensor del Pueblo.","La autoridad administrativa en asuntos de su competencia."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">La autoridad administrativa en asuntos de su competencia</mark></span>Según el <span class=\"ref-norma\">art. 10.Dos de la Ley Orgánica 3/1981 del Defensor del Pueblo</span>: <span class=\"ref-concepto\">\"Los Diputados y Senadores individualmente, las comisiones de investigación o relacionadas con la defensa general o parcial de los derechos y libertades públicas y, principalmente, la Comisión Mixta Congreso-Senado de relaciones con el Defensor del Pueblo podrán solicitar, mediante escrito motivado, la intervención del Defensor del Pueblo\"</span> La autoridad administrativa no figura entre quienes pueden solicitar la intervención por esta vía (art. 10.Tres: «No podrá presentar quejas ante el Defensor del Pueblo ninguna autoridad administrativa en asuntos de su competencia»)."},{"i":"14-30","p":"Ley Orgánica 3/1981, de 6 de abril, del Defensor del Pueblo. Cuál, entre otros, de los siguientes podrán solicitar mediante escrito motivado la intervención del Defensor del Pueblo para la investigación o esclarecimiento de actos, resoluciones y conductas concretas producidas en las Administraciones públicas, que afecten a un ciudadano o grupo de ciudadanos, en el ámbito de sus competencias. Señale la incorrecta.","o":["Los Diputados individualmente.","Los Senadores individualmente.","Cualquier comisión del Congreso con interés legítimo.","Principalmente, la Comisión Mixta Congreso-Senado de relaciones con el Defensor del Pueblo."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Cualquier comisión del Congreso con interés legítimo.</mark></span><span class=\"ref-norma\">Art. 10 · Ley Orgánica 3/1981, de 6 de abril, del Defensor del Pueblo</span>. El artículo 10.Uno de la Ley Orgánica 3/1981 establece que se puede dirigir al Defensor del Pueblo toda persona natural o jurídica que invoque un interés legítimo. No incluye específicamente a &quot;Cualquier comisión del Congreso con interés legítimo&quot; entre los legitimados directamente para presentar quejas. Además, los Diputados, Senadores y la Comisión Mixta no inician la investigación mediante &quot;escrito motivado&quot; como se describe. La opción d) es la más incorrecta en el contexto de la presentación de quejas individuales, ya que la Comisión Mixta es el órgano de relación. No obstante, en un test, la opción c) que no está expresamente en la lista de legitimados directos y la d) que describe la función de la Comisión de forma confusa en este contexto, son susceptibles de generar dudas. Considerando que el artículo 10 de la Ley no menciona a comisiones con interés legítimo, la opción c) es la incorrecta en la práctica."},{"i":"14-182","p":"Ley Orgánica 3/1981, de 6 de abril, del Defensor del Pueblo. El Defensor del Pueblo estará auxiliado por un Adjunto Primero y un Adjunto Segundo, en los que podrá delegar sus funciones y que le sustituirán por su orden, en el ejercicio de las mismas:","o":["En los supuestos de imposibilidad permanente y en los de cese.","En los supuestos de imposibilidad perpetua y en los de cese.","En los supuestos de imposibilidad duradera y en los de cese.","En los supuestos de imposibilidad temporal y en los de cese."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">En los supuestos de imposibilidad temporal y en los de cese.</mark></span><span class=\"ref-norma\">Art. 10.1 · Ley Orgánica 3/1981, de 6 de abril, del Defensor del Pueblo</span>. Los Adjuntos sustituyen al Defensor por su orden en los supuestos de imposibilidad temporal y en los de cese (Art. 10.1 LO 3/1981)."},{"i":"14-190","p":"Reglamento de Organización y Funcionamiento del Defensor del Pueblo, aprobado por las Mesas del Congreso y del Senado, a propuesta del Defensor del Pueblo, en su reunión conjunta de 6 de abril de 1983. Corresponde al Gabinete Técnico: señale la INCORRECTA.","o":["Organizar y dirigir la Secretaría particular del Defensor del Pueblo.","Ejercer las funciones de protocolo.","Realizar los estudios e informes que se le encomienden.","Dirigir las investigaciones que lleve a cabo el Defensor del Pueblo."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Dirigir las investigaciones que lleve a cabo el Defensor del Pueblo</mark></span>Dirigir las investigaciones no figura entre sus funciones; organizar la Secretaría particular sí. Según el <span class=\"ref-norma\">art. 10.2 del Reglamento de Organización y Funcionamiento del Defensor del Pueblo</span>: <span class=\"ref-concepto\">\"Corresponde al Gabinete Técnico organizar y dirigir la Secretaría particular del Defensor del Pueblo, realizar los estudios e informes que se le encomienden y ejercer las funciones de protocolo\"</span> (verificado con el texto oficial)."},{"i":"14-203","p":"(Reglamento) Reglamento de Organización y Funcionamiento del Defensor del Pueblo. El Defensor del Pueblo podrá estar asistido por un Gabinete Técnico, bajo la dirección de ___________ que designará y cesará libremente.","o":["Los Asesores.","Los Auxiliares.","Los Adjuntos.","El Secretario General."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Los Asesores</mark></span>Según el <span class=\"ref-norma\">art. 10.1 del Reglamento de Organización y Funcionamiento del Defensor del Pueblo</span>: <span class=\"ref-concepto\">\"El Defensor del Pueblo podrá estar asistido por un Gabinete Técnico, bajo la dirección de uno de los Asesores que designará y cesará libremente\"</span> (verificado con el texto oficial)."},{"i":"14-239","p":"Ley Orgánica 3/1981, de 6 de abril, del Defensor del Pueblo. Cuál, entre otros, de los siguientes podrá solicitar mediante escrito motivado la intervención del Defensor del Pueblo para la investigación o esclarecimiento de actos, resoluciones y conductas concretas producidas en las Administraciones públicas, que afecten a un ciudadano o grupo de ciudadanos, en el ámbito de sus competencias. Señale la incorrecta.","o":["Los Diputados individualmente.","Los Senadores individualmente.","Cualquier comisión del Congreso con interés legítimo.","Principalmente, la Comisión Mixta Congreso-Senado de relaciones con el Defensor del Pueblo."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Cualquier comisión del Congreso con interés legítimo.</mark></span><span class=\"ref-norma\">Art. 10 · Ley Orgánica 3/1981, de 6 de abril, del Defensor del Pueblo</span>. El Art. 10.Dos de la LO 3/1981 legitima a los Diputados y Senadores individualmente, a las comisiones de investigación o relacionadas con la defensa de los derechos y libertades públicas, y principalmente a la Comisión Mixta; no a \"cualquier comisión del Congreso con interés legítimo\"."},{"i":"14-ia-17","p":"LO 3/1981, del Defensor del Pueblo, art. 10.1. Sobre quién puede dirigirse al Defensor del Pueblo, señale la INCORRECTA:","o":["El internamiento en un centro penitenciario o de reclusión constituye un impedimento para dirigirse al Defensor del Pueblo.","Puede dirigirse toda persona natural o jurídica que invoque un interés legítimo, sin restricción alguna.","La nacionalidad, la residencia y el sexo no pueden constituir impedimento, como tampoco cualquier relación especial de sujeción o dependencia de una Administración o Poder público.","La minoría de edad y la incapacidad legal del sujeto no pueden constituir impedimento."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">El internamiento en un centro penitenciario o de reclusión constituye un impedimento para dirigirse al Defensor del Pueblo</mark></span>El <span class=\"ref-norma\">art. 10.1 de la LO 3/1981, del Defensor del Pueblo</span> dispone: <span class=\"ref-concepto\">\"No podrán constituir impedimento para ello la nacionalidad, residencia, sexo, minoría de edad, la incapacidad legal del sujeto, el internamiento en un centro penitenciario o de reclusión o, en general, cualquier relación especial de sujeción o dependencia de una Administración o Poder público\"</span>. Por qué fallan las otras: el internamiento penitenciario figura precisamente entre las circunstancias que NO pueden ser impedimento; las otras tres opciones reproducen correctamente el art. 10.1. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA · Dificultad: Media)</em>"},{"i":"14-ia-129","p":"Ley Orgánica 3/1981, de 6 de abril, del Defensor del Pueblo. Quién puede dirigirse. Podrá dirigirse al Defensor del Pueblo toda persona natural o jurídica que invoque un interés legítimo, sin restricción alguna. No podrán constituir impedimento para ello:","o":["la nacionalidad y la residencia, pero sí la minoría de edad.","la nacionalidad, la residencia y el sexo, pero sí el internamiento en un centro penitenciario, conforme al procedimiento que reglamentariamente se establezca.","la incapacidad legal del sujeto, pero sí la relación de dependencia de una Administración.","la nacionalidad, residencia, sexo, minoría de edad, la incapacidad legal del sujeto y el internamiento en un centro penitenciario o de reclusión."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">la nacionalidad, residencia, sexo, minoría de edad, la incapacidad legal del sujeto y el internamiento en un centro penitenciario o de reclusión</mark></span>El <span class=\"ref-norma\">art. 10.1 de la LO 3/1981</span> dispone: <span class=\"ref-concepto\">\"No podrán constituir impedimento para ello la nacionalidad, residencia, sexo, minoría de edad, la incapacidad legal del sujeto, el internamiento en un centro penitenciario o de reclusión\"</span> La lista de no-impedimentos es amplia: incluye minoría de edad, incapacidad e internamiento."},{"i":"14-ia-130","p":"Ley Orgánica 3/1981, de 6 de abril, del Defensor del Pueblo. Quién no puede presentar quejas. No podrá presentar quejas ante el Defensor del Pueblo:","o":["ninguna autoridad administrativa en asuntos de su competencia.","ningún funcionario en asuntos que afecten a su servicio, sin perjuicio de lo que establezcan los tratados internacionales.","ninguna persona jurídica de derecho público.","ningún Diputado o Senador individualmente."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">ninguna autoridad administrativa en asuntos de su competencia</mark></span>El <span class=\"ref-norma\">art. 10.3 de la LO 3/1981</span> dispone: <span class=\"ref-concepto\">\"No podrá presentar quejas ante el Defensor del Pueblo ninguna autoridad administrativa en asuntos de su competencia.\"</span> Excluida la autoridad administrativa en asuntos de su competencia."},{"i":"14-ia-189","p":"Reglamento de Organización y Funcionamiento del Defensor del Pueblo, aprobado por las Mesas del Congreso y del Senado, a propuesta del Defensor del Pueblo, en su reunión conjunta de 6 de abril de 1983. Gabinete Técnico. El Defensor del Pueblo podrá estar asistido por un Gabinete Técnico, bajo la dirección de uno de los Asesores que:","o":["designará la Junta de Coordinación y Régimen Interior.","propondrá el Secretario General.","designará y cesará libremente.","nombrará previa conformidad de la Comisión Mixta."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">designará y cesará libremente</mark></span>El <span class=\"ref-norma\">art. 10.1 de la Reglamento del Defensor del Pueblo</span> dispone: <span class=\"ref-concepto\">\"bajo la dirección de uno de los Asesores que designará y cesará libremente.\"</span> Lo designa y cesa libremente el Defensor."},{"i":"14-ia-190","p":"Reglamento de Organización y Funcionamiento del Defensor del Pueblo, aprobado por las Mesas del Congreso y del Senado, a propuesta del Defensor del Pueblo, en su reunión conjunta de 6 de abril de 1983. Gabinete Técnico. Corresponde al Gabinete Técnico organizar y dirigir la Secretaría particular del Defensor del Pueblo, realizar los estudios e informes que se le encomienden y ejercer:","o":["las funciones de protocolo.","las funciones de prensa e información.","las funciones de coordinación con las Comunidades Autónomas.","las funciones del Registro General."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">las funciones de protocolo</mark></span>El <span class=\"ref-norma\">art. 10.2 de la Reglamento del Defensor del Pueblo</span> dispone: <span class=\"ref-concepto\">\"realizar los estudios e informes que se le encomienden y ejercer las funciones de protocolo.\"</span> Funciones de protocolo."},{"i":"14-ia-191","p":"Reglamento de Organización y Funcionamiento del Defensor del Pueblo, aprobado por las Mesas del Congreso y del Senado, a propuesta del Defensor del Pueblo, en su reunión conjunta de 6 de abril de 1983. Gabinete de Prensa. El Defensor del Pueblo podrá establecer un Gabinete de Prensa e Información bajo su inmediata dependencia o:","o":["la del Secretario General.","la de la Junta de Coordinación y Régimen Interior.","la del Adjunto Primero.","la del Adjunto en quien él delegue."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">la del Adjunto en quien él delegue</mark></span>El <span class=\"ref-norma\">art. 10.3 de la Reglamento del Defensor del Pueblo</span> dispone: <span class=\"ref-concepto\">\"bajo su inmediata dependencia o del Adjunto en quien él delegue.\"</span> Del Defensor o del Adjunto en quien delegue."}]},{"a":"Artículo 28 — Sugerencias y modificación de criterios ✱","q":[{"i":"14-ia-224","p":"Reglamento de Organización y Funcionamiento del Defensor del Pueblo, aprobado por las Mesas del Congreso y del Senado, a propuesta del Defensor del Pueblo, en su reunión conjunta de 6 de abril de 1983. Coordinación con las Comunidades Autónomas. El Defensor del Pueblo ejercerá la alta coordinación entre sus propias competencias y las atribuidas a los órganos similares que puedan constituirse en las Comunidades Autónomas, sin perjuicio de:","o":["la supervisión de la Comisión Mixta.","la autonomía que les corresponda en la fiscalización de la actividad de las respectivas Administraciones autonómicas.","los convenios de colaboración que puedan suscribirse, salvo que el órgano competente acuerde otra cosa de forma motivada.","las competencias de los Parlamentos autonómicos."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">la autonomía que les corresponda en la fiscalización de la actividad de las respectivas Administraciones autonómicas</mark></span>El <span class=\"ref-norma\">art. 28.1 de la Reglamento del Defensor del Pueblo</span> dispone: <span class=\"ref-concepto\">\"sin perjuicio de la autonomía que les corresponda en la fiscalización de la actividad de las respectivas Administraciones autonómicas.\"</span> Respeta la autonomía de los órganos autonómicos."}]},{"a":"Artículo 6 — Excedencia especial","q":[{"i":"14-31","p":"Reglamento de Organización y Funcionamiento del Defensor del Pueblo, aprobado por las Mesas del Congreso y del Senado, a propuesta del Defensor del Pueblo, en su reunión conjunta de 6 de abril de 1983. Señale la incorrecta.","o":["El Defensor del Pueblo cesará en el desempeño de sus funciones por las causas y de acuerdo con lo establecido en los artículos 5.º y 7.º de la Ley Orgánica. En esos supuestos, desempeñarán sus funciones, interinamente y en su propio orden, los Adjuntos.","Tanto el Defensor del Pueblo como los Adjuntos Primero y Segundo tendrán el tratamiento que corresponda a su categoría constitucional.","El nombramiento del Defensor del Pueblo o de sus Adjuntos, si fueran funcionarios públicos, implicará su paso a la situación de excedencia especial con destino en el Cuerpo o Carrera de procedencia.","La elección del Defensor del Pueblo y de los Adjuntos se realizará de acuerdo con lo dispuesto en su Ley Orgánica y en los Reglamentos del Congreso de los Diputados y del Senado o de las Cortes Generales, en su caso."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">El nombramiento del Defensor del Pueblo o de sus Adjuntos, si fueran funcionarios públicos, implicará su paso a la situación de excedencia especial con destino en el Cuerpo o Carrera de procedencia</mark></span>La opción C es la incorrecta («con destino en el Cuerpo»); la D es literal del art. 4. Según el <span class=\"ref-norma\">art. 6 del Reglamento de Organización y Funcionamiento del Defensor del Pueblo</span>: <span class=\"ref-concepto\">\"El nombramiento del Defensor del Pueblo o de los Adjuntos, si fueran funcionarios públicos, implicará su pase a la situación de excedencia especial o equivalente en la Carrera o Cuerpo de procedencia\"</span> (verificado con el texto oficial)."},{"i":"14-48","p":"Reglamento de Organización y Funcionamiento del Defensor del Pueblo, aprobado por las Mesas del Congreso y del Senado y, a propuesta del Defensor del Pueblo, en su reunión conjunta de 6 de abril de 1983. Señale la incorrecta","o":["El Defensor del Pueblo cesará en el desempeño de sus funciones por las causas y de acuerdo con lo establecido en los artículos 5.º y 7.º de la Ley Orgánica. En esos supuestos, desempeñarán sus funciones, interinamente y en su propio orden, los Adjuntos.","Tanto el Defensor del Pueblo como los Adjuntos Primero y Segundo tendrán el tratamiento que corresponda a su categoría constitucional.","El nombramiento del Defensor del Pueblo o de sus Adjuntos, si fueran funcionarios públicos, implicará su paso a la situación de excedencia especial con destino en el Cuerpo o Carrera de procedencia.","La elección del Defensor del Pueblo y de los Adjuntos se realizará de acuerdo con lo dispuesto en su Ley Orgánica y en los Reglamentos del Congreso de los Diputados y del Senado o de las Cortes Generales, en su caso."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">El nombramiento del Defensor del Pueblo o de sus Adjuntos, si fueran funcionarios públicos, implicará su paso a la situación de excedencia especial con destino en el Cuerpo o Carrera de procedencia</mark></span>La opción C es la incorrecta («con destino en el Cuerpo»); la D es literal del art. 4. Según el <span class=\"ref-norma\">art. 6 del Reglamento de Organización y Funcionamiento del Defensor del Pueblo</span>: <span class=\"ref-concepto\">\"El nombramiento del Defensor del Pueblo o de los Adjuntos, si fueran funcionarios públicos, implicará su pase a la situación de excedencia especial o equivalente en la Carrera o Cuerpo de procedencia\"</span> (verificado con el texto oficial)."},{"i":"14-77","p":"Señale la incorrecta","o":["El Defensor del Pueblo cesará en el desempeño de sus funciones por las causas y de acuerdo con lo establecido en los artículos 5.º y 7.º de la Ley Orgánica. En esos supuestos, desempeñarán sus funciones, sucesoria y conjuntamente los Adjuntos.","Tanto el Defensor del Pueblo como los Adjuntos Primero y Segundo tendrán el tratamiento que corresponda a su categoría constitucional.","El nombramiento del Defensor del Pueblo o de sus Adjuntos, si fueran funcionarios públicos, implicará su paso a la situación de excedencia especial con destino en el Cuerpo o Carrera de procedencia.","La elección del Defensor del Pueblo y de los Adjuntos se realizará de acuerdo con lo dispuesto en su Ley Orgánica y en los Reglamentos del Congreso de los Diputados y del Senado o de las Cortes Generales, en su caso."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">El nombramiento del Defensor del Pueblo o de sus Adjuntos, si fueran funcionarios públicos, implicará su paso a la situación de excedencia especial con destino en el Cuerpo o Carrera de procedencia</mark></span>La opción C es la incorrecta («con destino en el Cuerpo»); la D es literal del art. 4. Según el <span class=\"ref-norma\">art. 6 del Reglamento de Organización y Funcionamiento del Defensor del Pueblo</span>: <span class=\"ref-concepto\">\"El nombramiento del Defensor del Pueblo o de los Adjuntos, si fueran funcionarios públicos, implicará su pase a la situación de excedencia especial o equivalente en la Carrera o Cuerpo de procedencia\"</span> (verificado con el texto oficial)."},{"i":"14-ia-30","p":"Reglamento del Defensor del Pueblo, art. 6. El nombramiento del Defensor del Pueblo o de los Adjuntos, si fueran funcionarios públicos, implicará su pase a la situación de:","o":["Servicio activo en su Cuerpo de origen, con reserva de la plaza que ocupasen, durante todo el mandato.","Servicios especiales con reserva de destino.","Excedencia especial o equivalente en la Carrera o Cuerpo de procedencia.","Excedencia voluntaria por interés particular."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Excedencia especial o equivalente en la Carrera o Cuerpo de procedencia</mark></span>El <span class=\"ref-norma\">art. 6 del Reglamento de Organización y Funcionamiento del Defensor del Pueblo</span> dispone: <span class=\"ref-concepto\">\"implicará su pase a la situación de excedencia especial o equivalente en la Carrera o Cuerpo de procedencia\"</span>. Por qué fallan las otras: el Reglamento prevé expresamente la excedencia especial o equivalente; permanecer en activo sería incompatible con el cargo (art. 7.1 LO). <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA · Dificultad: Media)</em>"},{"i":"14-ia-181","p":"Reglamento de Organización y Funcionamiento del Defensor del Pueblo, aprobado por las Mesas del Congreso y del Senado, a propuesta del Defensor del Pueblo, en su reunión conjunta de 6 de abril de 1983. Excedencia especial. El nombramiento del Defensor del Pueblo o de los Adjuntos, si fueran funcionarios públicos, implicará su pase a la situación de:","o":["servicios especiales.","excedencia voluntaria por interés particular.","excedencia especial o equivalente en la Carrera o Cuerpo de procedencia.","suspensión provisional de funciones en su Cuerpo de origen, salvo que el órgano competente acuerde otra cosa de forma motivada."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">excedencia especial o equivalente en la Carrera o Cuerpo de procedencia</mark></span>El <span class=\"ref-norma\">art. 6 de la Reglamento del Defensor del Pueblo</span> dispone: <span class=\"ref-concepto\">\"implicará su pase a la situación de excedencia especial o equivalente en la Carrera o Cuerpo de procedencia.\"</span> Excedencia especial o equivalente."}]},{"a":"Artículo 12 — Competencias de los Adjuntos ✱ R11","q":[{"i":"14-22","p":"Ley Orgánica 3/1981, de 6 de abril, del Defensor del Pueblo. Ámbito de competencias. Señale la correcta.","o":["El Defensor del Pueblo podrá en todo caso, de oficio o a instancia de parte, supervisar por sí mismo la actividad de la Comunidad Autónoma en el ámbito de competencias definido por esta Ley.","El Defensor del Pueblo podrá en determinados casos de oficio o a instancia de parte, supervisar por sí mismo la actividad de la Comunidad Autónoma en el ámbito de competencias definido por esta Ley.","Los órganos similares de las Comunidades Autónomas no tienen que coordinar sus funciones con las del Defensor del Pueblo en los casos de que el Defensor del Pueblo supervise su actividad.","Todas son incorrectas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">El Defensor del Pueblo podrá en todo caso, de oficio o a instancia de parte, supervisar por sí mismo la actividad de la Comunidad Autónoma …</mark></span><span class=\"ref-norma\">Art. 12 · Ley Orgánica 3/1981, de 6 de abril, del Defensor del Pueblo</span>. El artículo 12.Uno de la Ley Orgánica 3/1981 establece que el Defensor del Pueblo podrá, en todo caso, de oficio o a instancia de parte, supervisar por sí mismo la actividad de la Comunidad Autónoma en el ámbito de competencias definido por esta Ley."},{"i":"14-24","p":"Reglamento de Organización y Funcionamiento del Defensor del Pueblo, aprobado por las Mesas del Congreso y del Senado, a propuesta del Defensor del Pueblo, en su reunión conjunta de 6 de abril de 1983. El Adjunto en el que el Defensor del Pueblo delegue las funciones del Mecanismo Nacional de Prevención:","o":["Asumirá la Vicepresidencia de su Consejo Asesor.","Asumirá la presidencia de su Consejo Asesor.","Asumirá la presidencia del Consejo Asesor de las Cámaras.","Asumirá la vicepresidencia del Consejo Asesor de las Cámaras."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Asumirá la presidencia de su Consejo Asesor</mark></span>Según el <span class=\"ref-norma\">art. 12.3 del Reglamento de Organización y Funcionamiento del Defensor del Pueblo</span>: <span class=\"ref-concepto\">\"El Adjunto en el que el Defensor del Pueblo delegue las funciones del Mecanismo Nacional de Prevención asumirá la presidencia de su Consejo asesor\"</span> (verificado con el texto oficial)."},{"i":"14-65","p":"El Adjunto en el que el Defensor del Pueblo delegue las funciones del Mecanismo Nacional de Prevención:","o":["Asumirá la vicepresidencia de su Consejo Asesor.","Asumirá la presidencia de su Consejo Asesor.","Asumirá la presidencia del Consejo Asesor de las Cámaras.","Asumirá la vicepresidencia del Consejo Asesor de las Cámaras."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Asumirá la presidencia de su Consejo Asesor</mark></span>Según el <span class=\"ref-norma\">art. 12.3 del Reglamento de Organización y Funcionamiento del Defensor del Pueblo</span>: <span class=\"ref-concepto\">\"El Adjunto en el que el Defensor del Pueblo delegue las funciones del Mecanismo Nacional de Prevención asumirá la presidencia de su Consejo asesor\"</span> (verificado con el texto oficial)."},{"i":"14-191","p":"Ley Orgánica 3/1981, de 6 de abril, del Defensor del Pueblo. ¿En qué casos no se interrumpirá la actividad del Defensor del Pueblo?","o":["En los casos en que el Gobierno no se encuentre reunido.","En los casos en que el Consejo General del Poder Judicial haya expirado su mandato.","En los casos en que las Cortes Generales no se encuentren reunidas, hubieren sido disueltas o hubiere expirado su mandato, y tampoco por la declaración de los estados de excepción o de sitio.","En ningún caso se interrumpirá, ni siquiera por disolución de las Cortes Generales."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">En los casos en que las Cortes Generales no se encuentren reunidas, hubieren sido disueltas o hubiere expirado su mandato, y tampoco por la…</mark></span><span class=\"ref-norma\">Art. 12 · Ley Orgánica 3/1981, de 6 de abril, del Defensor del Pueblo</span>. La actividad del Defensor no se interrumpe por la no reunión, disolución o expiración del mandato de las Cortes (Art. 12) ni por la declaración de los estados de excepción o de sitio (Art. 13 LO 3/1981)."},{"i":"14-194","p":"Ley Orgánica 3/1981, de 6 de abril, del Defensor del Pueblo. Ámbito de competencias. Señale la INCORRECTA:","o":["El Defensor del Pueblo podrá, en todo caso, de oficio o a instancia de parte, supervisar por sí mismo la actividad de la Comunidad Autónoma en el ámbito de competencias definido por esta Ley.","El Defensor del Pueblo no podrá, en ningún caso, supervisar por sí mismo la actividad de la Comunidad Autónoma en el ámbito de competencias definido por esta Ley.","Los órganos similares de las Comunidades Autónomas coordinarán sus funciones con las del Defensor del Pueblo y éste podrá solicitar su cooperación.","El Defensor del Pueblo velará por el respeto de los derechos proclamados en el título primero de la Constitución, en el ámbito de la Administración Militar, sin que ello pueda entorpecer o interferir en el mando de la Defensa Nacional."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">El Defensor del Pueblo no podrá, en ningún caso, supervisar por sí mismo la actividad de la Comunidad Autónoma en el ámbito de competencias…</mark></span><span class=\"ref-norma\">Art. 12.1 · Ley Orgánica 3/1981, de 6 de abril, del Defensor del Pueblo</span>. La opción (b) es incorrecta, ya que el Defensor sí tiene competencia para supervisar la actividad de la Administración en el ámbito de las Comunidades Autónomas (Art. 12.1 LO 3/1981)."},{"i":"14-235","p":"Ley Orgánica 3/1981, de 6 de abril, del Defensor del Pueblo. Ámbito de competencias. Señale la correcta.","o":["El Defensor del Pueblo podrá en todo caso, de oficio o a instancia de parte, supervisar por sí mismo la actividad de la Comunidad Autónoma en el ámbito de competencias definido por esta Ley.","El Defensor del Pueblo podrá en determinados casos, de oficio o a instancia de parte, supervisar por sí mismo la actividad de la Comunidad Autónoma en el ámbito de competencias definido por esta Ley.","Los órganos similares de las Comunidades Autónomas no tienen que coordinar sus funciones con las del Defensor del Pueblo en los casos en que el Defensor del Pueblo supervise su actividad.","Todas son incorrectas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">El Defensor del Pueblo podrá en todo caso, de oficio o a instancia de parte, supervisar por sí mismo la actividad de la Comunidad Autónom…</mark></span><span class=\"ref-norma\">Art. 12 · Ley Orgánica 3/1981, de 6 de abril, del Defensor del Pueblo</span>. El Art. 12.Uno de la LO 3/1981 establece que el Defensor del Pueblo podrá, en todo caso, de oficio o a instancia de parte, supervisar por sí mismo la actividad de la Comunidad Autónoma en el ámbito de competencias definido por la Ley."},{"i":"14-ia-19","p":"LO 3/1981, del Defensor del Pueblo, art. 12.2. En la supervisión de la actividad de las Comunidades Autónomas, los órganos similares al Defensor del Pueblo de las mismas:","o":["Ejercerán la supervisión en exclusiva y sin intervención alguna del Defensor del Pueblo, que no podrá solicitar su cooperación ni actuar en su ámbito.","Coordinarán sus funciones con las del Defensor del Pueblo, que podrá solicitar su cooperación.","Quedarán subordinados jerárquicamente al Defensor del Pueblo.","Solo podrán relacionarse con él a través de la Comisión Mixta Congreso-Senado."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Coordinarán sus funciones con las del Defensor del Pueblo, que podrá solicitar su cooperación</mark></span>El <span class=\"ref-norma\">art. 12.2 de la LO 3/1981, del Defensor del Pueblo</span> dispone: <span class=\"ref-concepto\">\"los órganos similares de las Comunidades Autónomas coordinarán sus funciones con las del Defensor del Pueblo y éste podrá solicitar su cooperación\"</span>. Por qué fallan las otras: la relación es de coordinación y cooperación (no exclusión, jerarquía ni intermediación de la Comisión Mixta). <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA · Dificultad: Media)</em>"},{"i":"14-ia-33","p":"Reglamento del Defensor del Pueblo, art. 12.4. La admisión definitiva o el rechazo y, en su caso, la resolución última de las quejas formuladas corresponde acordarla:","o":["A los Adjuntos, en todo caso, sin que el Defensor del Pueblo pueda avocar ni sustituirles en ello.","Al Defensor del Pueblo o al Adjunto en quien delegue o que le sustituya.","Al Secretario General.","A la Junta de Coordinación y Régimen Interior."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Al Defensor del Pueblo o al Adjunto en quien delegue o que le sustituya</mark></span>El <span class=\"ref-norma\">art. 12.4 del Reglamento de Organización y Funcionamiento del Defensor del Pueblo</span> dispone: <span class=\"ref-concepto\">\"La admisión definitiva o el rechazo y, en su caso, la resolución última de las quejas formuladas corresponde acordarla al Defensor del Pueblo o al Adjunto en quien delegue o que le sustituya\"</span>. Por qué fallan las otras: los Adjuntos solo proponen la admisión o el rechazo (art. 12.1.b); la decisión última es del Defensor o del Adjunto delegado o sustituto. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA · Dificultad: Media)</em>"},{"i":"14-ia-44","p":"Reglamento del Defensor del Pueblo, art. 12.5. El Defensor del Pueblo podrá recabar el conocimiento, dirección o tratamiento de cualquier queja o investigación cuyo trámite corresponda a los Adjuntos, oída:","o":["La Comisión Mixta Congreso-Senado.","La Junta de Coordinación y Régimen Interior.","El Consejo Asesor del Mecanismo Nacional de Prevención.","El Secretario General."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">La Junta de Coordinación y Régimen Interior</mark></span>El <span class=\"ref-norma\">art. 12.5 del Reglamento de Organización y Funcionamiento del Defensor del Pueblo</span> dispone: <span class=\"ref-concepto\">\"El Defensor del Pueblo podrá recabar, oída la Junta de Coordinación y Régimen Interior, el conocimiento, dirección o tratamiento de cualquier queja o investigación cuyo trámite corresponda a los Adjuntos\"</span>. Por qué fallan las otras: el órgano consultivo interno previsto es la Junta; ni la Comisión Mixta, ni el Consejo Asesor (propio del MNP), ni el Secretario General. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA · Dificultad: Difícil)</em>"},{"i":"14-ia-133","p":"Ley Orgánica 3/1981, de 6 de abril, del Defensor del Pueblo. Comunidades Autónomas. A los efectos de supervisar la actividad de la Comunidad Autónoma, los órganos similares de las Comunidades Autónomas coordinarán sus funciones con las del Defensor del Pueblo y éste podrá solicitar:","o":["su subordinación.","su informe preceptivo.","su delegación de competencias.","su cooperación."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">su cooperación</mark></span>El <span class=\"ref-norma\">art. 12 de la LO 3/1981</span> dispone: <span class=\"ref-concepto\">\"los órganos similares de las Comunidades Autónomas coordinarán sus funciones con las del Defensor del Pueblo y éste podrá solicitar su cooperación.\"</span> Coordinación y cooperación, no subordinación."},{"i":"14-ia-195","p":"Reglamento de Organización y Funcionamiento del Defensor del Pueblo, aprobado por las Mesas del Congreso y del Senado, a propuesta del Defensor del Pueblo, en su reunión conjunta de 6 de abril de 1983. Competencias de los Adjuntos. Corresponde a los Adjuntos dirigir la tramitación, comprobación e investigación de las quejas formuladas y de las actuaciones que se inicien de oficio, proponiendo, en su caso, al Defensor del Pueblo:","o":["la suspensión de la investigación y el archivo de las quejas.","el traslado de las quejas al Ministerio Fiscal y al Consejo General del Poder Judicial, conforme al procedimiento que reglamentariamente se establezca.","la delegación de la instrucción en el Gabinete Técnico.","la admisión a trámite o rechazo de las mismas y las resoluciones que se estimen procedentes."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">la admisión a trámite o rechazo de las mismas y las resoluciones que se estimen procedentes</mark></span>El <span class=\"ref-norma\">art. 12.1.b) de la Reglamento del Defensor del Pueblo</span> dispone: <span class=\"ref-concepto\">\"proponiendo, en su caso, al Defensor del Pueblo, la admisión a trámite o rechazo de las mismas y las resoluciones que se estimen procedentes.\"</span> Proponen admisión o rechazo y resoluciones."},{"i":"14-ia-196","p":"Reglamento de Organización y Funcionamiento del Defensor del Pueblo, aprobado por las Mesas del Congreso y del Senado, a propuesta del Defensor del Pueblo, en su reunión conjunta de 6 de abril de 1983. Delimitación de funciones de los Adjuntos. La delimitación de los respectivos ámbitos de funciones de los dos Adjuntos se llevará a cabo por el Defensor del Pueblo, poniéndose en conocimiento de:","o":["la Junta de Coordinación y Régimen Interior, sin perjuicio de lo que establezcan los tratados internacionales.","la Comisión Mixta constituida en las Cortes Generales en relación con el citado Defensor.","las Mesas de ambas Cámaras.","el Presidente del Congreso de los Diputados."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">la Comisión Mixta constituida en las Cortes Generales en relación con el citado Defensor</mark></span>El <span class=\"ref-norma\">art. 12.2 de la Reglamento del Defensor del Pueblo</span> dispone: <span class=\"ref-concepto\">\"poniéndose en conocimiento de la Comisión Mixta constituida en las Cortes Generales en relación con el citado Defensor.\"</span> La delimita el Defensor y lo comunica a la Comisión Mixta."},{"i":"14-ia-197","p":"Reglamento de Organización y Funcionamiento del Defensor del Pueblo, aprobado por las Mesas del Congreso y del Senado, a propuesta del Defensor del Pueblo, en su reunión conjunta de 6 de abril de 1983. Adjunto Primero. Sin perjuicio de lo establecido en el artículo 8 del Reglamento, el Adjunto Primero asumirá la coordinación de los servicios dependientes del Defensor del Pueblo, así como el despacho ordinario con el Secretario General. En su defecto, asumirá las expresadas funciones:","o":["el Director designado por el Defensor del Pueblo.","el Secretario General.","el Adjunto Segundo.","el Vocal de mayor edad del Consejo Asesor."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">el Adjunto Segundo</mark></span>El <span class=\"ref-norma\">art. 12.2 de la Reglamento del Defensor del Pueblo</span> dispone: <span class=\"ref-concepto\">\"En su defecto, asumirá las expresadas funciones el Adjunto Segundo.\"</span> Suple el Adjunto Segundo."},{"i":"14-ia-198","p":"Reglamento de Organización y Funcionamiento del Defensor del Pueblo, aprobado por las Mesas del Congreso y del Senado, a propuesta del Defensor del Pueblo, en su reunión conjunta de 6 de abril de 1983. Admisión y resolución de las quejas. La admisión definitiva o el rechazo y, en su caso, la resolución última de las quejas formuladas corresponde acordarla:","o":["al Defensor del Pueblo o al Adjunto en quien delegue o que le sustituya.","al Adjunto que haya instruido la queja.","a la Junta de Coordinación y Régimen Interior, en los términos que determine la ley orgánica correspondiente.","exclusivamente al Defensor del Pueblo."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">al Defensor del Pueblo o al Adjunto en quien delegue o que le sustituya</mark></span>El <span class=\"ref-norma\">art. 12.4 de la Reglamento del Defensor del Pueblo</span> dispone: <span class=\"ref-concepto\">\"corresponde acordarla al Defensor del Pueblo o al Adjunto en quien delegue o que le sustituya.\"</span> Defensor, o Adjunto delegado o sustituto."},{"i":"14-ia-199","p":"Reglamento de Organización y Funcionamiento del Defensor del Pueblo, aprobado por las Mesas del Congreso y del Senado, a propuesta del Defensor del Pueblo, en su reunión conjunta de 6 de abril de 1983. Avocación de quejas. El Defensor del Pueblo podrá recabar, oída la Junta de Coordinación y Régimen Interior, el conocimiento, dirección o tratamiento de cualquier queja o investigación cuyo trámite corresponda:","o":["al Secretario General.","al Gabinete Técnico.","a los Asesores responsables de área.","a los Adjuntos."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">a los Adjuntos</mark></span>El <span class=\"ref-norma\">art. 12.5 de la Reglamento del Defensor del Pueblo</span> dispone: <span class=\"ref-concepto\">\"cuyo trámite corresponda a los Adjuntos.\"</span> Puede avocar lo tramitado por los Adjuntos, oída la Junta."}]},{"a":"Artículo 16 — Cese de los Adjuntos","q":[{"i":"14-117","p":"Los Adjuntos al Defensor del Pueblo NO cesarán por alguna de las siguientes causas:","o":["Por renuncia.","Por expiración del plazo de su nombramiento.","Por incapacidad sobrevenida.","Por imprevisión en el cumplimiento de las obligaciones y deberes del cargo."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Por imprevisión en el cumplimiento de las obligaciones y deberes del cargo.</mark></span><span class=\"ref-norma\">Art. 16 · El Defensor del Pueblo</span>. El Reglamento de Organización y Funcionamiento del Defensor del Pueblo (art. 16) establece las causas de cese de los Adjuntos, que son: renuncia, expiración del plazo, muerte o incapacidad sobrevenida, e incumplimiento notorio de las obligaciones o deberes del cargo o haber sido condenado por delito doloso. La causa es &quot;notoria negligencia o incumplimiento notorio&quot; (LO 3/1981, art. 5.1.4ª, aplicable a los Adjuntos por el art. 8.4), no &quot;imprevisión&quot;."},{"i":"14-204","p":"(Reglamento) Reglamento de Organización y Funcionamiento del Defensor del Pueblo. Causas por las que los Adjuntos al Defensor del Pueblo cesarán: señale la CORRECTA.","o":["Por haber sido condenado, por delito doloso o imprudente.","Por muerte o por incapacidad sobrevenida.","Por notoria negligencia en el cumplimiento de las obligaciones y deberes del cargo. En este caso, el cese exigirá una propuesta razonada de la Comisión mixta Congreso-Senado, que habrá de ser aprobada por el Defensor del Pueblo, de acuerdo con el mismo procedimiento y mayoría requerida para otorgar la conformidad previa para su nombramiento, y con audiencia del interesado.","Todas son correctas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Por muerte o por incapacidad sobrevenida</mark></span>Según el <span class=\"ref-norma\">art. 16.1 del Reglamento de Organización y Funcionamiento del Defensor del Pueblo</span>: <span class=\"ref-concepto\">\"c) Por muerte o por incapacidad sobrevenida\"</span> La A es falsa (delito doloso, mediante sentencia firme) y la C invierte el procedimiento: la propuesta razonada es del Defensor del Pueblo y la aprueba la Comisión Mixta."},{"i":"14-ia-3","p":"LO 3/1981, del Defensor del Pueblo, art. 16.1. La correspondencia dirigida al Defensor del Pueblo y remitida desde cualquier centro de detención, internamiento o custodia de las personas:","o":["Podrá ser censurada previa autorización judicial.","No podrá ser objeto de censura de ningún tipo.","Podrá ser revisada por el director del centro antes de su envío.","Solo podrá ser censurada durante los estados de excepción o de sitio."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">No podrá ser objeto de censura de ningún tipo</mark></span>El <span class=\"ref-norma\">art. 16.1 de la LO 3/1981, del Defensor del Pueblo</span> dispone: <span class=\"ref-concepto\">\"La correspondencia dirigida al Defensor del Pueblo y que sea remitida desde cualquier centro de detención, internamiento o custodia de las personas no podrá ser objeto de censura de ningún tipo\"</span>. Por qué fallan las otras: la prohibición es absoluta («de ningún tipo»): no cabe censura judicial, administrativa ni por razón de estados excepcionales. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA · Dificultad: Fácil)</em>"},{"i":"14-ia-36","p":"Reglamento del Defensor del Pueblo, art. 16.1.d. El cese de los Adjuntos del Defensor del Pueblo por notoria negligencia en el cumplimiento de las obligaciones y deberes del cargo exigirá:","o":["Una propuesta del Presidente del Congreso, aprobada por las tres quintas partes de cada Cámara.","Una decisión libre del Defensor del Pueblo, con audiencia del interesado y comunicación posterior a la Comisión mixta Congreso-Senado y a los Presidentes de ambas Cámaras, sin necesidad de más trámites ni mayorías especiales.","Una propuesta razonada del Defensor del Pueblo, aprobada por la Comisión mixta Congreso-Senado con el mismo procedimiento y mayoría que para otorgar la conformidad previa a su nombramiento, y con audiencia del interesado.","Una propuesta razonada del Defensor del Pueblo, aprobada por mayoría absoluta del Senado."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Una propuesta razonada del Defensor del Pueblo, aprobada por la Comisión mixta Congreso-Senado con el mismo procedimiento y mayoría que para otorgar la conformidad previa a su nombramiento, y con audiencia del interesado</mark></span>El <span class=\"ref-norma\">art. 16.1.d del Reglamento de Organización y Funcionamiento del Defensor del Pueblo</span> dispone: <span class=\"ref-concepto\">\"En este caso, el cese exigirá una propuesta razonada del Defensor del Pueblo, que habrá de ser aprobada por la Comisión mixta Congreso-Senado, de acuerdo con el mismo procedimiento y mayoría requerida para otorgar la conformidad previa para su nombramiento, y con audiencia del interesado\"</span>. Por qué fallan las otras: la negligencia notoria es la única causa de cese que exige propuesta razonada y aprobación de la Comisión Mixta con audiencia del interesado; las otras opciones cambian el órgano o la mayoría. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA · Dificultad: Difícil)</em>"},{"i":"14-ia-138","p":"Ley Orgánica 3/1981, de 6 de abril, del Defensor del Pueblo. Centros de detención. La correspondencia dirigida al Defensor del Pueblo y que sea remitida desde cualquier centro de detención, internamiento o custodia de las personas:","o":["no podrá ser objeto de censura de ningún tipo.","solo podrá ser objeto de censura por orden judicial motivada.","podrá ser objeto de control por el director del centro.","no podrá ser objeto de censura, salvo en los estados de excepción o de sitio."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">no podrá ser objeto de censura de ningún tipo</mark></span>El <span class=\"ref-norma\">art. 16 de la LO 3/1981</span> dispone: <span class=\"ref-concepto\">\"no podrá ser objeto de censura de ningún tipo.\"</span> Sin censura de ningún tipo."},{"i":"14-ia-204","p":"Reglamento de Organización y Funcionamiento del Defensor del Pueblo, aprobado por las Mesas del Congreso y del Senado, a propuesta del Defensor del Pueblo, en su reunión conjunta de 6 de abril de 1983. Cese de los Adjuntos. En el cese de los Adjuntos por notoria negligencia en el cumplimiento de las obligaciones y deberes del cargo, el cese exigirá una propuesta razonada del Defensor del Pueblo, que habrá de ser aprobada por la Comisión mixta Congreso-Senado:","o":["por mayoría absoluta y con audiencia del interesado.","de acuerdo con el mismo procedimiento y mayoría requerida para otorgar la conformidad previa para su nombramiento, y con audiencia del interesado.","por mayoría de las tres quintas partes y con audiencia de las Mesas de las Cámaras, salvo que el órgano competente acuerde otra cosa de forma motivada.","por mayoría simple y sin necesidad de audiencia del interesado."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">de acuerdo con el mismo procedimiento y mayoría requerida para otorgar la conformidad previa para su nombramiento, y con audiencia del interesado</mark></span>El <span class=\"ref-norma\">art. 16.1.d) de la Reglamento del Defensor del Pueblo</span> dispone: <span class=\"ref-concepto\">\"que habrá de ser aprobada por la Comisión mixta Congreso-Senado, de acuerdo con el mismo procedimiento y mayoría requerida para otorgar la conformidad previa para su nombramiento, y con audiencia del interesado.\"</span> Mismo procedimiento y mayoría que para la conformidad previa, con audiencia."},{"i":"14-ia-205","p":"Reglamento de Organización y Funcionamiento del Defensor del Pueblo, aprobado por las Mesas del Congreso y del Senado, a propuesta del Defensor del Pueblo, en su reunión conjunta de 6 de abril de 1983. Publicación del cese. El cese de los Adjuntos se publicará en el «Boletín Oficial del Estado» y en:","o":["el «Boletín Oficial de la Comisión Mixta».","los Diarios de Sesiones de ambas Cámaras.","los de ambas Cámaras.","el Boletín Oficial del Congreso únicamente."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">los de ambas Cámaras</mark></span>El <span class=\"ref-norma\">art. 16.2 de la Reglamento del Defensor del Pueblo</span> dispone: <span class=\"ref-concepto\">\"El cese de los Adjuntos se publicará en el «Boletín Oficial del Estado» y en los de ambas Cámaras.\"</span> BOE y boletines de ambas Cámaras."}]},{"a":"Artículo 26 — Registro, Archivo y Oficina de Información R13","q":[{"i":"14-67","p":"El Registro General de la Institución dependerá:","o":["Del Gabinete Técnico.","Del Jefe del Régimen Económico.","Directamente del Secretario General.","Del Jefe del Régimen Interior, Estudio, Documentación y Publicaciones."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Del Jefe del Régimen Interior, Estudio, Documentación y Publicaciones</mark></span>Depende de ese Servicio, no directamente del Secretario General. Según el <span class=\"ref-norma\">art. 26.1 del Reglamento de Organización y Funcionamiento del Defensor del Pueblo</span>: <span class=\"ref-concepto\">\"Dependiendo del Servicio de Régimen Interior, Estudio, Documentación y Publicaciones, existirá un Registro General y una Oficina de Información\"</span> (verificado con el texto oficial)."},{"i":"14-69","p":"La Sección de Archivo dependerá:","o":["Directamente del Secretario General.","Del Servicio de Régimen Económico.","Del Servicio de Régimen Interior, Estudio, Documentación y Publicaciones.","Directamente del Defensor Adjunto Primero."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Directamente del Secretario General</mark></span>Según el <span class=\"ref-norma\">art. 26.2 del Reglamento de Organización y Funcionamiento del Defensor del Pueblo</span>: <span class=\"ref-concepto\">\"Bajo la directa responsabilidad del Secretario general, se constituirá la Sección de Archivo\"</span> (verificado con el texto oficial)."}]},{"a":"Artículo 31 — Personal al servicio del Defensor","q":[{"i":"14-184","p":"Ley Orgánica 3/1981, de 6 de abril, del Defensor del Pueblo. ¿Qué informes, presentados por el Defensor del Pueblo a las Cortes, serán publicados?","o":["Los informes anuales y, en su caso, los extraordinarios.","Los informes mensuales y, en su caso, los extraordinarios.","Los informes anuales y, en su caso, los ordinarios.","Los informes semestrales y, en su caso, los extraordinarios."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Los informes anuales y, en su caso, los extraordinarios.</mark></span><span class=\"ref-norma\">Art. 31.3 · Ley Orgánica 3/1981, de 6 de abril, del Defensor del Pueblo</span>. Los informes anuales y, si los hubiere, los extraordinarios, serán publicados (Art. 31.3 LO 3/1981)."},{"i":"14-243","p":"Reglamento de Organización y Funcionamiento del Defensor del Pueblo. Personal al servicio del Defensor del Pueblo. La selección del personal al servicio del Defensor del Pueblo se realizará libremente, con arreglo a los principios de:","o":["Mérito, capacidad y antigüedad.","Mérito y capacidad.","Capacidad y antigüedad.","Mérito, capacidad y libre designación."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Mérito y capacidad.</mark></span><span class=\"ref-norma\">Art. 31 · Reglamento de Organización y Funcionamiento del Defensor del Pueblo</span> dispone: <span class=\"ref-concepto\">\"La selección del personal al servicio del Defensor del Pueblo se realizará por éste libremente, con arreglo a los principios de mérito y capacidad. En estos nombramientos se procurará dar prioridad a funcionarios públicos.\"</span> El Art. 31.3 del Reglamento establece que la selección del personal se realizará libremente por el Defensor del Pueblo, con arreglo a los principios de mérito y capacidad."},{"i":"14-ia-27","p":"LO 3/1981, del Defensor del Pueblo, art. 31.2. Cuando la intervención se hubiere iniciado a solicitud de un parlamentario o Comisión (art. 10.2), el Defensor del Pueblo:","o":["Solo informará si el parlamentario o la Comisión lo piden de nuevo por escrito una vez finalizadas sus investigaciones, y no si decide no intervenir.","Informará únicamente a la Comisión Mixta Congreso-Senado.","No está obligado a informar cuando desestime la solicitud.","Les informará de los resultados alcanzados al término de sus investigaciones y, si decide no intervenir, informará razonando su desestimación."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Les informará de los resultados alcanzados al término de sus investigaciones y, si decide no intervenir, informará razonando su desestimación</mark></span>El <span class=\"ref-norma\">art. 31.2 de la LO 3/1981, del Defensor del Pueblo</span> dispone: <span class=\"ref-concepto\">\"el Defensor del Pueblo informará al parlamentario o Comisión competente que lo hubiese solicitado y al término de sus investigaciones, de los resultados alcanzados. Igualmente, cuando decida no intervenir informará razonando su desestimación\"</span>. Por qué fallan las otras: hay deber de informar tanto del resultado como de la desestimación (motivada), y al solicitante concreto, no solo a la Comisión Mixta. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA · Dificultad: Media)</em>"},{"i":"14-ia-46","p":"LO 3/1981, del Defensor del Pueblo, art. 31.3. El Defensor del Pueblo comunicará el resultado positivo o negativo de sus investigaciones:","o":["A la Comisión Mixta Congreso-Senado, que lo remitirá a la autoridad, funcionario o dependencia afectada para su conocimiento.","Únicamente a las Cortes Generales en el informe anual.","A la autoridad, funcionario o dependencia administrativa acerca de la cual se haya suscitado la queja.","Al Ministro del Departamento afectado, en todo caso."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">A la autoridad, funcionario o dependencia administrativa acerca de la cual se haya suscitado la queja</mark></span>El <span class=\"ref-norma\">art. 31.3 de la LO 3/1981, del Defensor del Pueblo</span> dispone: <span class=\"ref-concepto\">\"El Defensor del Pueblo comunicará el resultado positivo o negativo de sus investigaciones a la autoridad, funcionario o dependencia administrativa acerca de la cual se haya suscitado\"</span>. Por qué fallan las otras: la comunicación es directa a la autoridad, funcionario o dependencia investigada, sin pasar por la Comisión Mixta y sin limitarse al informe anual ni al Ministro. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA · Dificultad: Difícil)</em>"},{"i":"14-ia-164","p":"Ley Orgánica 3/1981, de 6 de abril, del Defensor del Pueblo. Notificaciones. El Defensor del Pueblo informará al interesado del resultado de sus investigaciones y gestión, así como de la respuesta que hubiese dado la Administración o funcionario implicados, salvo en el caso de que éstas, por su naturaleza, fuesen consideradas como:","o":["de carácter confidencial o declaradas materia clasificada.","de interés general o de seguridad nacional.","de contenido sancionador o disciplinario.","de carácter reservado o declaradas secretas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">de carácter reservado o declaradas secretas</mark></span>El <span class=\"ref-norma\">art. 31.1 de la LO 3/1981</span> dispone: <span class=\"ref-concepto\">\"salvo en el caso de que éstas, por su naturaleza, fuesen consideradas como de carácter reservado o declaradas secretas.\"</span> Reservadas o secretas."},{"i":"14-ia-228","p":"Reglamento de Organización y Funcionamiento del Defensor del Pueblo, aprobado por las Mesas del Congreso y del Senado, a propuesta del Defensor del Pueblo, en su reunión conjunta de 6 de abril de 1983. Selección del personal. La selección del personal al servicio del Defensor del Pueblo se realizará por éste libremente, con arreglo a los principios de mérito y capacidad. En estos nombramientos se procurará:","o":["dar prioridad a personal laboral de las Cortes.","dar prioridad a funcionarios públicos.","respetar el orden de una lista de espera.","oír a la Junta de Coordinación y Régimen Interior."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">dar prioridad a funcionarios públicos</mark></span>El <span class=\"ref-norma\">art. 31.3 de la Reglamento del Defensor del Pueblo</span> dispone: <span class=\"ref-concepto\">\"En estos nombramientos se procurará dar prioridad a funcionarios públicos.\"</span> Prioridad a funcionarios públicos."},{"i":"14-ia-229","p":"Reglamento de Organización y Funcionamiento del Defensor del Pueblo, aprobado por las Mesas del Congreso y del Senado, a propuesta del Defensor del Pueblo, en su reunión conjunta de 6 de abril de 1983. Funcionario eventual. El personal que no reúna las condiciones de funcionario de carrera de las Administraciones públicas tendrá el carácter de:","o":["personal laboral temporal.","funcionario interino de las Cortes.","funcionario eventual al servicio del Defensor del Pueblo.","personal de confianza del Defensor del Pueblo, salvo que el órgano competente acuerde otra cosa de forma motivada."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">funcionario eventual al servicio del Defensor del Pueblo</mark></span>El <span class=\"ref-norma\">art. 31.4 de la Reglamento del Defensor del Pueblo</span> dispone: <span class=\"ref-concepto\">\"tendrá el carácter de funcionario eventual al servicio del Defensor del Pueblo.\"</span> Funcionario eventual."}]},{"a":"Artículo 32 — Composición del personal","q":[{"i":"14-27","p":"Ley Orgánica 3/1981, de 6 de abril, del Defensor del Pueblo. Informe a las Cortes.","o":["En el informe no constarán en ningún caso datos personales que permitan la privada identificación de los interesados en el procedimiento investigador.","El informe contendrá igualmente un anexo cuyo destinatario será la Comisión Mixta Congreso-Senado de relaciones con el Defensor del Pueblo, en el que se hará constar la liquidación del presupuesto anual de la Institución en el periodo que corresponda.","Un resumen del informe oral, expuesto posteriormente por el Defensor del Pueblo ante el Congreso de los Diputados, pudiendo intervenir los grupos parlamentarios a efectos de debatir y determinar su postura.","Los informes anuales y, en su caso, los extraordinarios, serán publicados."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Los informes anuales y, en su caso, los extraordinarios, serán publicados.</mark></span><span class=\"ref-norma\">Art. 32 · Ley Orgánica 3/1981, de 6 de abril, del Defensor del Pueblo</span>. El artículo 32.Tres de la Ley Orgánica 3/1981 establece que &quot;Los informes anuales y, en su caso, los extraordinarios, serán publicados.&quot;"},{"i":"14-34","p":"Ley Orgánica 3/1981, de 6 de abril, del Defensor del Pueblo. Informe a las Cortes. El Defensor del Pueblo dará cuenta ___________ a las Cortes Generales de la gestión realizada en un informe que presentará ante las mismas cuando se hallen reunidas en periodo ordinario de sesiones.","o":["Trimestralmente.","Cada dos años.","Anualmente.","Periódicamente."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Anualmente.</mark></span><span class=\"ref-norma\">Art. 32 · Ley Orgánica 3/1981, de 6 de abril, del Defensor del Pueblo</span>. El artículo 32.Uno de la Ley Orgánica 3/1981 establece que el Defensor del Pueblo dará cuenta anualmente a las Cortes Generales de la gestión realizada en un informe."},{"i":"14-45","p":"Reglamento de Organización y Funcionamiento del Defensor del Pueblo. El personal al servicio de la Institución del Defensor del Pueblo estará compuesto por, entre otros. Señale la INCORRECTA.","o":["Asesores responsables de área.","Asesores técnicos.","Administrativos.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span>Las tres opciones nombradas figuran en la lista, por eso no hay ninguna incorrecta. Según el <span class=\"ref-norma\">art. 32 del Reglamento de Organización y Funcionamiento del Defensor del Pueblo</span>: <span class=\"ref-concepto\">\"El personal al servicio de la Institución del Defensor del Pueblo estará compuesto por los Asesores-responsables de área, Asesores-técnicos, administrativos, auxiliares y subalternos\"</span> (verificado con el texto oficial)."},{"i":"14-99","p":"Reglamento de Organización y Funcionamiento del Defensor del Pueblo, aprobado por las Mesas del Congreso y del Senado, a propuesta del Defensor del Pueblo, en su reunión conjunta de 6 de abril de 1983. La condición de asesor del Defensor del Pueblo, además, es incompatible. Señale la INCORRECTA.","o":["Con todo mandato representativo.","Con todo cargo político.","Con la afiliación a cualquier partido político.","Con el ejercicio de funciones directivas en un Sindicato."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Con la afiliación a cualquier partido político.</mark></span><span class=\"ref-norma\">Art. 32 · Reglamento de Organización y Funcionamiento del Defensor del Pueblo</span>. El artículo 32 del ROF (1983) establece las incompatibilidades para el personal al servicio del Defensor del Pueblo. La afiliación a cualquier partido político no está entre las incompatibilidades, sino que la LO 3/1981 y el ROF prohíben al Defensor y a sus Adjuntos pertenecer a partidos políticos o sindicatos (Artículo 7.1 LO). Para el personal al servicio del Defensor, el ROF (art. 32) solo habla de que no pueden ser asesores los que estén incursos en incompatibilidades legalmente establecidas o realicen actividades que impidan el cumplimiento de sus deberes. La prohibición de afiliación a un partido político se aplica al Defensor y sus Adjuntos, no al resto del personal o asesores. La opción (c) es la INCORRECTA porque no se recoge como incompatibilidad en la LO ni en el ROF para los asesores. Nota: Se asume que se refiere a incompatibilidades del personal de la Institución y, específicamente a los asesores, aunque la literalidad de la opción (c) es la más claramente incorrecta como incompatibilidad general para el personal."},{"i":"14-121","p":"Ley Orgánica 3/1981, de 6 de abril, del Defensor del Pueblo. El Defensor del Pueblo dará cuenta ____________ a las Cortes Generales de la gestión realizada en un informe que presentará ante las mismas cuando se hallen reunidas en periodo ordinario de sesiones.","o":["Sincrónicamente.","Anualmente.","Bianualmente.","Sin estar sujeto a plazos establecidos."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Anualmente.</mark></span><span class=\"ref-norma\">Art. 32.1 · Ley Orgánica 3/1981, de 6 de abril, del Defensor del Pueblo</span>. El artículo 32.1 de la LO 3/1981 establece que el Defensor del Pueblo dará cuenta anualmente a las Cortes Generales de la gestión realizada en un informe que presentará ante las mismas cuando se hallen reunidas en periodo ordinario de sesiones."},{"i":"14-135","p":"(LO 3/1981 - Informe anual) Ley Orgánica 3/1981, de 6 de abril, del Defensor del Pueblo. El Defensor del Pueblo dará cuenta ____________ a las Cortes Generales de la gestión realizada en un informe que presentará ante las mismas cuando se hallen reunidas en periodo ordinario de sesiones.","o":["Sincrónicamente.","Anualmente.","Bianualmente.","Sin estar sujeto a plazos establecidos."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Anualmente.</mark></span><span class=\"ref-norma\">Art. 32.1 · Ley Orgánica 3/1981, de 6 de abril, del Defensor del Pueblo</span>. El art. 32.1 de la LO 3/1981 establece que el Defensor del Pueblo dará cuenta anualmente a las Cortes Generales."},{"i":"14-143","p":"(LO 3/1981 - Informe) Ley Orgánica 3/1981, de 6 de abril, del Defensor del Pueblo. Informe a las Cortes. El Defensor del Pueblo dará cuenta a las Cortes Generales de la gestión realizada en un informe que presentará ante las mismas cuando se hallen reunidas en periodo ordinario de sesiones:","o":["Trimestralmente.","Semestralmente.","Anualmente.","Mensualmente."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Anualmente.</mark></span><span class=\"ref-norma\">Art. 32.1 · Ley Orgánica 3/1981, de 6 de abril, del Defensor del Pueblo</span>. El art. 32.1 de la LO 3/1981 establece que el informe a las Cortes Generales es anual."},{"i":"14-151","p":"(Ley Orgánica 3/1981) Ley Orgánica 3/1981, de 6 de abril, del Defensor del Pueblo. Cuando la gravedad o urgencia de los hechos lo aconsejen podrá presentar __________________ que dirigirá a las Diputaciones Permanentes de las Cámaras si éstas no se encontraran reunidas.","o":["Un informe ordinario.","Un informe extraordinario.","Un informe urgente.","Un informe preeminente."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Un informe extraordinario.</mark></span><span class=\"ref-norma\">Art. 32.2 · Ley Orgánica 3/1981, de 6 de abril, del Defensor del Pueblo</span>. El artículo 32.2 de la LO 3/1981 permite al Defensor del Pueblo presentar un informe extraordinario si la gravedad o urgencia lo aconsejan, dirigiéndolo a las Diputaciones Permanentes si las Cámaras no estuvieran reunidas."},{"i":"14-165","p":"(LO 3/1981 - Informe Anual) Ley Orgánica 3/1981, de 6 de abril, del Defensor del Pueblo. El Defensor del Pueblo dará cuenta ____________ a las Cortes Generales de la gestión realizada en un informe que presentará ante las mismas cuando se hallen reunidas en periodo ordinario de sesiones.","o":["Anualmente.","Semestralmente.","Trimestralmente.","Mensualmente."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Anualmente.</mark></span><span class=\"ref-norma\">Art. 32.1 · Ley Orgánica 3/1981, de 6 de abril, del Defensor del Pueblo</span>. El artículo 32.1 de la LO 3/1981 establece que el informe a las Cortes Generales es anual."},{"i":"14-186","p":"Ley Orgánica 3/1981, de 6 de abril, del Defensor del Pueblo. En el informe no constará ______________ que permitan la pública identificación de los interesados en el procedimiento investigador.","o":["información económica.","Datos personales.","Información analítica.","Información estadística."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Datos personales.</mark></span><span class=\"ref-norma\">Art. 32.2 · Ley Orgánica 3/1981, de 6 de abril, del Defensor del Pueblo</span>. El informe anual no contendrá datos personales que permitan la pública identificación de los interesados en el procedimiento investigador, salvo con su expreso consentimiento (Art. 32.2 LO 3/1981)."},{"i":"14-240","p":"Reglamento de Organización y Funcionamiento del Defensor del Pueblo. El personal al servicio de la Institución del Defensor del Pueblo estará compuesto por: Señale la incorrecta.","o":["Asesores responsables de área.","Asesores técnicos.","Ayudantes administrativos.","Subalternos."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Ayudantes administrativos.</mark></span><span class=\"ref-norma\">Art. 32 · Reglamento de Organización y Funcionamiento del Defensor del Pueblo</span>. El Art. 32 del Reglamento clasifica al personal en Asesores-responsables de área, Asesores-técnicos, administrativos, auxiliares y subalternos; no existe la categoría de \"Ayudantes administrativos\"."},{"i":"14-241","p":"Ley Orgánica 3/1981, de 6 de abril, del Defensor del Pueblo. Informe a las Cortes. El Defensor del Pueblo dará cuenta ______________ a las Cortes Generales de la gestión realizada en un informe que presentará ante las mismas cuando se hallen reunidas en período ordinario de sesiones.","o":["Trimestralmente.","Cada dos años.","Anualmente.","Periódicamente."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Anualmente.</mark></span><span class=\"ref-norma\">Art. 32 · Ley Orgánica 3/1981, de 6 de abril, del Defensor del Pueblo</span>. El Art. 32.Uno de la LO 3/1981 establece que el Defensor del Pueblo dará cuenta anualmente a las Cortes Generales de la gestión realizada."},{"i":"14-ia-165","p":"Ley Orgánica 3/1981, de 6 de abril, del Defensor del Pueblo. Informe anual. El Defensor del Pueblo dará cuenta anualmente a las Cortes Generales de la gestión realizada en un informe que presentará ante las mismas:","o":["cuando se hallen reunidas en periodo ordinario de sesiones.","durante el primer periodo de sesiones de cada año, sin perjuicio de lo que establezcan los tratados internacionales.","en el mes de enero de cada año.","cuando lo soliciten las Mesas de ambas Cámaras."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">cuando se hallen reunidas en periodo ordinario de sesiones</mark></span>El <span class=\"ref-norma\">art. 32.1 de la LO 3/1981</span> dispone: <span class=\"ref-concepto\">\"en un informe que presentará ante las mismas cuando se hallen reunidas en periodo ordinario de sesiones.\"</span> En periodo ordinario de sesiones."},{"i":"14-ia-166","p":"Ley Orgánica 3/1981, de 6 de abril, del Defensor del Pueblo. Informe extraordinario. Cuando la gravedad o urgencia de los hechos lo aconsejen, el Defensor del Pueblo podrá presentar un informe extraordinario que dirigirá a las Diputaciones Permanentes de las Cámaras:","o":["en todo caso.","si éstas no se encontraran reunidas.","cuando haya sido disuelto el Congreso.","cuando lo solicite la Comisión Mixta."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">si éstas no se encontraran reunidas</mark></span>El <span class=\"ref-norma\">art. 32.2 de la LO 3/1981</span> dispone: <span class=\"ref-concepto\">\"que dirigirá a las Diputaciones Permanentes de las Cámaras si éstas no se encontraran reunidas.\"</span> A las Diputaciones Permanentes si las Cámaras no están reunidas."},{"i":"14-ia-230","p":"Reglamento de Organización y Funcionamiento del Defensor del Pueblo, aprobado por las Mesas del Congreso y del Senado, a propuesta del Defensor del Pueblo, en su reunión conjunta de 6 de abril de 1983. Composición del personal. El personal al servicio de la Institución del Defensor del Pueblo estará compuesto por los Asesores-responsables de área, Asesores-técnicos, administrativos, auxiliares y:","o":["subalternos.","ayudantes.","técnicos de gestión.","letrados."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">subalternos</mark></span>El <span class=\"ref-norma\">art. 32 de la Reglamento del Defensor del Pueblo</span> dispone: <span class=\"ref-concepto\">\"estará compuesto por los Asesores-responsables de área, Asesores-técnicos, administrativos, auxiliares y subalternos.\"</span> Subalternos."}]},{"a":"REGLAMENTO · RÉGIMEN DISCIPLINARIO: PRESCRIPCIÓN Y SANCIONES (ARTS. 36 A 38)","q":[{"i":"14-35","p":"Reglamento de Organización y Funcionamiento del Defensor del Pueblo, aprobado por las Mesas del Congreso y del Senado. Régimen disciplinario. Las sanciones por falta grave prescribirán a:","o":["Al año.","Los seis meses.","Los dos años.","Los cuatro meses."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Los seis meses</mark></span>Según el <span class=\"ref-norma\">art. 36.3 del Reglamento de Organización y Funcionamiento del Defensor del Pueblo</span>: <span class=\"ref-concepto\">\"Las faltas leves prescribirán a los dos meses; las graves, a los seis meses, y las muy graves, al año\"</span> (verificado con el texto oficial)."},{"i":"14-44","p":"Reglamento de Organización y Funcionamiento del Defensor del Pueblo. Régimen disciplinario. Las sanciones por FALTAS GRAVES y MUY GRAVES, se impondrán en virtud de expediente instruido al efecto y que constará de los trámites de:","o":["Pliego de cargos.","Pruebas, en su caso.","Propuesta de resolución.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas.</mark></span><span class=\"ref-norma\">Art. 36.1 · Reglamento de Organización y Funcionamiento del Defensor del Pueblo</span>. El procedimiento disciplinario para faltas graves y muy graves incluye, al menos, pliego de cargos, la práctica de pruebas (en su caso) y la propuesta de resolución (Art. 36.1 ROF)."},{"i":"14-242","p":"Reglamento de Organización y Funcionamiento del Defensor del Pueblo. Régimen disciplinario. Las sanciones por falta grave prescribirán a:","o":["Al año.","Los seis meses.","Los dos años.","Los cuatro meses."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Los seis meses.</mark></span><span class=\"ref-norma\">Art. 36.3 · Reglamento de Organización y Funcionamiento del Defensor del Pueblo</span>. El Art. 36.3 del Reglamento establece que las faltas leves prescribirán a los dos meses; las graves, a los seis meses, y las muy graves, al año."},{"i":"14-258","p":"Reglamento de Organización y Funcionamiento del Defensor del Pueblo. Régimen disciplinario. La prescripción de las faltas será:","o":["Leves a los tres meses, las graves al año y las muy graves al año.","Leves a los dos meses, las graves al año y las muy graves a los dos años.","Leves a los seis meses, las graves a los seis meses y las muy graves a los dos años.","Ninguna opción es correcta."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Ninguna opción es correcta.</mark></span><span class=\"ref-norma\">Art. 36.3 · Reglamento de Organización y Funcionamiento del Defensor del Pueblo</span>. El Art. 36.3 del Reglamento establece que las faltas leves prescribirán a los dos meses, las graves a los seis meses y las muy graves al año, combinación que no coincide con ninguna de las opciones a), b) o c)."},{"i":"14-ia-234","p":"Reglamento de Organización y Funcionamiento del Defensor del Pueblo, aprobado por las Mesas del Congreso y del Senado, a propuesta del Defensor del Pueblo, en su reunión conjunta de 6 de abril de 1983. Régimen disciplinario. El personal al servicio del Defensor del Pueblo podrá ser sancionado por la Comisión de faltas disciplinarias derivadas del incumplimiento de sus deberes de acuerdo con:","o":["el Estatuto del Personal de las Cortes Generales.","el presente Reglamento.","el Estatuto Básico del Empleado Público.","la Ley."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">la Ley</mark></span>El <span class=\"ref-norma\">art. 36.1 de la Reglamento del Defensor del Pueblo</span> dispone: <span class=\"ref-concepto\">\"derivadas del incumplimiento de sus deberes de acuerdo con la Ley.\"</span> De acuerdo con la Ley."},{"i":"14-ia-235","p":"Reglamento de Organización y Funcionamiento del Defensor del Pueblo, aprobado por las Mesas del Congreso y del Senado, a propuesta del Defensor del Pueblo, en su reunión conjunta de 6 de abril de 1983. Prescripción de las faltas. Las faltas leves prescribirán a los dos meses; las graves, a los seis meses, y las muy graves:","o":["al año.","a los dos años.","a los nueve meses.","a los tres años."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">al año</mark></span>El <span class=\"ref-norma\">art. 36.3 de la Reglamento del Defensor del Pueblo</span> dispone: <span class=\"ref-concepto\">\"Las faltas leves prescribirán a los dos meses; las graves, a los seis meses, y las muy graves, al año.\"</span> Muy graves: un año."}]}];
